// Configuração do fluxo incremental
const fs = require('fs');
const path = require('path');

const outputDir = '/output';
const controleFile = path.join(outputDir, 'contatos_controle.json');
const csvFile = path.join(outputDir, 'contatos_whatsapp_acumulado.csv');
const jsonFile = path.join(outputDir, 'contatos_whatsapp_acumulado.json');

// Criar diretório se não existir
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Carregar contatos já existentes
let contatosExistentes = [];
let numerosConhecidos = new Set();
let ultimaExecucao = null;

if (fs.existsSync(controleFile)) {
  try {
    const controle = JSON.parse(fs.readFileSync(controleFile, 'utf8'));
    contatosExistentes = controle.contatos || [];
    ultimaExecucao = controle.ultima_execucao || null;

    // Criar Set com números normalizados
    for (const c of contatosExistentes) {
      const num = (c.numero || '').replace(/\D/g, '');
      if (num) numerosConhecidos.add(num);
    }

    console.log(`Controle carregado: ${contatosExistentes.length} contatos existentes`);
  } catch (e) {
    console.log('Erro ao carregar controle, iniciando fresh:', e.message);
  }
}

return {
  json: {
    contatos_existentes: contatosExistentes,
    numeros_conhecidos: Array.from(numerosConhecidos),
    total_existentes: contatosExistentes.length,
    ultima_execucao: ultimaExecucao,
    output_dir: outputDir,
    controle_file: controleFile,
    csv_file: csvFile,
    json_file: jsonFile,
    api_version: 'v19.0',
    base_url: 'https://graph.facebook.com',
    max_pages: 50,
    limit: 100
  }
};

// Processar primeira página e preparar paginação
const controle = $('Carregar Controle').first().json;
const resposta = $input.first().json;

if (resposta.error) {
  return { json: { erro: true, mensagem: resposta.error.message } };
}

let todasConversas = resposta.data || [];
let paging = resposta.paging;

return {
  json: {
    conversas: todasConversas,
    total_acumulado: todasConversas.length,
    has_next: paging?.cursors?.after ? true : false,
    next_cursor: paging?.cursors?.after || null,
    paginas_processadas: 1,
    max_pages: controle.max_pages,
    numeros_conhecidos: controle.numeros_conhecidos,
    contatos_existentes: controle.contatos_existentes,
    controle_file: controle.controle_file,
    csv_file: controle.csv_file,
    json_file: controle.json_file,
    base_url: controle.base_url,
    api_version: controle.api_version,
    limit: controle.limit
  }
};

// Acumular conversas
const estado = $('Tem Mais?').first().json;
const nova = $input.first().json;

const novasConversas = nova.data || [];
const todasConversas = [...estado.conversas, ...novasConversas];

const paging = nova.paging;
const paginas = estado.paginas_processadas + 1;

return {
  json: {
    conversas: todasConversas,
    total_acumulado: todasConversas.length,
    has_next: paging?.cursors?.after && paginas < estado.max_pages ? true : false,
    next_cursor: paging?.cursors?.after || null,
    paginas_processadas: paginas,
    max_pages: estado.max_pages,
    numeros_conhecidos: estado.numeros_conhecidos,
    contatos_existentes: estado.contatos_existentes,
    controle_file: estado.controle_file,
    csv_file: estado.csv_file,
    json_file: estado.json_file,
    base_url: estado.base_url,
    api_version: estado.api_version,
    limit: estado.limit
  }
};

// Extrair contatos INCREMENTAL - apenas novos
const fs = require('fs');
const dados = $input.first().json;
const conversas = dados.conversas || [];
const phoneId = $env.WHATSAPP_PHONE_NUMBER_ID;

// Set de números já conhecidos
const numerosConhecidos = new Set(dados.numeros_conhecidos);
const contatosExistentes = dados.contatos_existentes;

// Map para novos contatos (para evitar duplicatas entre novas conversas)
const novosContatosMap = new Map();
let contatosAtualizados = 0;

for (const conversa of conversas) {
  if (!conversa.participants) continue;

  for (const p of conversa.participants) {
    if (p.id === phoneId || p.id === 'ADMIN') continue;

    // Normalizar número
    const numeroNormalizado = (p.wa_id || p.id || '').replace(/\D/g, '');
    if (!numeroNormalizado) continue;

    // Verificar se é NOVO contato
    if (!numerosConhecidos.has(numeroNormalizado)) {
      // Novo contato!
      let nome = p.name;
      if (!nome || nome === 'ADMIN') {
        nome = `Contato ${numeroNormalizado.slice(-4)}`;
      }

      // Verificar se já adicionamos neste ciclo
      if (!novosContatosMap.has(numeroNormalizado)) {
        novosContatosMap.set(numeroNormalizado, {
          nome: nome,
          numero: numeroNormalizado,
          whatsapp: p.wa_id || p.id,
          tipo: p.type || 'individual',
          conversa_id: conversa.id,
          ultima_interacao: conversa.start_time,
          ultima_mensagem: conversa.last_message?.text?.body || '',
          timestamp_mensagem: conversa.last_message?.timestamp || null,
          data_cadastro: new Date().toISOString(),
          origem: 'novo'
        });
      }
    } else {
      // Contato já existe - verificar se precisa atualizar dados
      const existente = contatosExistentes.find(c => {
        const numExistente = (c.numero || '').replace(/\D/g, '');
        return numExistente === numeroNormalizado;
      });

      if (existente && conversa.start_time) {
        // Atualizar se conversa mais recente
        if (!existente.ultima_interacao || conversa.start_time > existente.ultima_interacao) {
          existente.ultima_interacao = conversa.start_time;
          existente.conversa_id = conversa.id;
          if (conversa.last_message?.text?.body) {
            existente.ultima_mensagem = conversa.last_message.text.body;
          }
          existente.data_atualizacao = new Date().toISOString();
          existente.origem = 'atualizado';
          contatosAtualizados++;
        }
      }
    }
  }
}

// Converter novos contatos para array
const novosContatos = Array.from(novosContatosMap.values());

// Adicionar formato internacional
for (const c of novosContatos) {
  c.formato_internacional = formatarNumero(c.numero);
}
for (const c of contatosExistentes) {
  if (!c.formato_internacional) {
    c.formato_internacional = formatarNumero(c.numero);
  }
}

function formatarNumero(numero) {
  if (!numero) return '';
  if (numero.length === 13 && numero.startsWith('55')) {
    return `+55 (${numero.substring(2,4)}) ${numero.substring(4,9)}-${numero.substring(9)}`;
  }
  if (numero.length === 12 && numero.startsWith('55')) {
    return `+55 (${numero.substring(2,4)}) ${numero.substring(4,8)}-${numero.substring(8)}`;
  }
  return numero.startsWith('+') ? numero : '+' + numero;
}

// Combinar: existentes + novos (ordenados por data de cadastro)
const todosContatos = [...contatosExistentes, ...novosContatos];

// Ordenar por última interação
todosContatos.sort((a, b) => {
  if (!a.ultima_interacao) return 1;
  if (!b.ultima_interacao) return -1;
  return new Date(b.ultima_interacao) - new Date(a.ultima_interacao);
});

return {
  json: {
    total_final: todosContatos.length,
    total_existentes: contatosExistentes.length,
    total_novos: novosContatos.length,
    total_atualizados: contatosAtualizados,
    total_conversas: conversas.length,
    paginas_processadas: dados.paginas_processadas,
    contatos: todosContatos,
    novos_contatos: novosContatos,
    controle_file: dados.controle_file,
    csv_file: dados.csv_file,
    json_file: dados.json_file,
    timestamp: new Date().toISOString(),
    sucesso: true
  }
};

// Salvar todos os arquivos
const fs = require('fs');
const dados = $input.first().json;

const contatos = dados.contatos;
const novosContatos = dados.novos_contatos;

// ===== ARQUIVO DE CONTROLE (JSON com todos os dados) =====
const controle = {
  ultima_execucao: dados.timestamp,
  total_contatos: dados.total_final,
  total_novos_esta_execucao: dados.total_novos,
  paginas_processadas: dados.paginas_processadas,
  contatos: contatos
};
fs.writeFileSync(dados.controle_file, JSON.stringify(controle, null, 2), 'utf8');

// ===== CSV ACUMULADO (com BOM para Excel) =====
const headers = ['nome', 'numero', 'whatsapp', 'tipo', 'formato_internacional', 'ultima_interacao', 'ultima_mensagem', 'data_cadastro', 'origem'];
const csvLinhas = [headers.join(',')];

for (const c of contatos) {
  csvLinhas.push([
    escapeCsv(c.nome),
    c.numero,
    c.whatsapp,
    c.tipo,
    escapeCsv(c.formato_internacional),
    c.ultima_interacao || '',
    escapeCsv(c.ultima_mensagem || ''),
    c.data_cadastro || '',
    c.origem || ''
  ].join(','));
}

const csv = '\uFEFF' + csvLinhas.join('\n');
fs.writeFileSync(dados.csv_file, csv, 'utf8');

// ===== JSON COMPLETO =====
fs.writeFileSync(dados.json_file, JSON.stringify(contatos, null, 2), 'utf8');

// ===== ARQUIVO DE RESUMO (apenas novos desta execução) =====
if (novosContatos.length > 0) {
  const resumoFile = dados.csv_file.replace('.csv', '_novos_' + dados.timestamp.split('T')[0] + '.json');
  fs.writeFileSync(resumoFile, JSON.stringify({
    data_execucao: dados.timestamp,
    total_novos: novosContatos.length,
    novos_contatos: novosContatos
  }, null, 2), 'utf8');
}

function escapeCsv(valor) {
  if (!valor) return '';
  const str = String(valor);
  if (str.includes(',') || str.includes('"') || str.includes('\n')) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

return {
  json: {
    sucesso: true,
    total_final: dados.total_final,
    total_existentes: dados.total_existentes,
    total_novos: dados.total_novos,
    total_atualizados: dados.total_atualizados,
    paginas_processadas: dados.paginas_processadas,
    arquivos: {
      controle: dados.controle_file,
      csv: dados.csv_file,
      json: dados.json_file
    },
    mensagem: dados.total_novos > 0 
      ? `${dados.total_novos} novos contatos adicionados! Total: ${dados.total_final}`
      : `Nenhum contato novo. Total mantido: ${dados.total_final}`
  }
};
